class TaskQueue:
    def __init__(self):
        self._items = []

    def add(self, task_id, priority):
        self._items.append((priority, task_id))

    def pop(self):
        if not self._items:
            raise IndexError('empty')
        return self._items.pop()[1]

import unittest
from queueing import TaskQueue

class QueueTests(unittest.TestCase):
    def test_high_priority_first_then_id(self):
        q=TaskQueue(); q.add('b',2); q.add('a',2); q.add('c',5)
        self.assertEqual([q.pop(),q.pop(),q.pop()], ['c','a','b'])

    def test_duplicate_rejected(self):
        q=TaskQueue(); q.add('x',1)
        with self.assertRaises(ValueError): q.add('x',9)

if __name__ == '__main__':
    unittest.main()
